begin;
select plan(56);
select has_table('app_private','client_migration_batches','migration batch aggregate exists');
select has_table('app_private','client_migration_source_rows','immutable source rows exist');
select has_table('app_private','client_migration_row_versions','versioned interpretations exist');
select has_table('app_private','client_migration_row_decisions','review decisions exist');
select has_table('app_private','client_migration_row_outcomes','row outcomes exist');
select has_table('app_private','client_migration_entity_provenance','entity provenance exists');
select has_function('api','client_migration_dry_run',array['uuid','uuid','integer','uuid'],'true dry run boundary exists');
select has_function('api','client_migration_activate_batch',array['uuid','uuid','integer','uuid'],'batch activation boundary exists');
select has_function('api','client_migration_bulk_review_safe',array['uuid','uuid','text','text','uuid'],'narrow safe bulk review boundary exists');
select has_function('api','client_migration_rows',array['uuid','uuid','jsonb'],'row list read boundary exists');
select has_function('api','client_migration_row_detail',array['uuid','uuid'],'row detail read boundary exists');
select has_function('api','client_migration_report',array['uuid','uuid'],'reconciliation report read boundary exists');

insert into auth.users(id,email) values('76000000-0000-4000-8000-000000000001','migration-manager@test.invalid'),('76000000-0000-4000-8000-000000000002','migration-driver@test.invalid'),('76000000-0000-4000-8000-000000000003','migration-region@test.invalid');
insert into public.user_profiles(user_id,display_name) values('76000000-0000-4000-8000-000000000001','Migration Manager'),('76000000-0000-4000-8000-000000000002','Migration Driver'),('76000000-0000-4000-8000-000000000003','Regional Reviewer');
insert into app_private.user_roles(user_id,role_id) select '76000000-0000-4000-8000-000000000001'::uuid,role_id from app_private.roles where role_key='operations_manager' union all select '76000000-0000-4000-8000-000000000002'::uuid,role_id from app_private.roles where role_key='driver_team' union all select '76000000-0000-4000-8000-000000000003'::uuid,role_id from app_private.roles where role_key='operations_manager';
insert into app_private.user_access_scopes(user_id,scope_kind,scope_id) values('76000000-0000-4000-8000-000000000001','global',null),('76000000-0000-4000-8000-000000000002','team','54000000-0000-0000-0000-000000000001'),('76000000-0000-4000-8000-000000000003','service_region',gen_random_uuid());
insert into app_private.client_contacts(client_id,contact_name,mobile_e164,email,is_primary) values('57000000-0000-0000-0000-000000000001','Existing Migration Contact','+27825550101','migration-existing@example.invalid',true);
update app_private.client_services set lifecycle_status='active' where client_id='57000000-0000-0000-0000-000000000001' and service_address_id='58000000-0000-0000-0000-000000000001';
insert into app_private.client_migration_team_mappings values('canonical_csv','canonical-v1','TEAM-A','54000000-0000-0000-0000-000000000001',now());

create temporary table migration_ids(batch_id uuid);
insert into migration_ids select (api.client_migration_create_batch('76000000-0000-4000-8000-000000000001','{"sourceType":"canonical_csv","sourceName":"synthetic.csv","sourceFileHash":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","environment":"local","mappingVersion":"canonical-v1"}',gen_random_uuid())->>'client_migration_batch_id')::uuid;
select is((select lifecycle_status from app_private.client_migration_batches),'created','batch created');
select is((select mapping_version from app_private.client_migration_batches),'canonical-v1','mapping version retained');
select ok((select source_file_hash=repeat('a',64) from app_private.client_migration_batches),'source hash retained');
select lives_ok(format($f$select api.client_migration_import_rows(%L,%L,1,%L::jsonb,gen_random_uuid())$f$,'76000000-0000-4000-8000-000000000001',(select batch_id from migration_ids),'[{"rowNumber":2,"rowKey":"NEW-1","externalClientReference":"NEW-1","fingerprint":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb","payload":{"legacyClientReference":"NEW-1","clientName":"Synthetic New Client","contactName":"New Contact","mobile":"082 123 4567","email":"NEW@EXAMPLE.INVALID","addressLine1":"1 Synthetic Migration Road","suburb":"Test Suburb","city":"Pretoria","latitude":-25.70,"longitude":28.27,"drumCount":2,"serviceStartDate":"2026-01-01","collectionDay":1,"team":"TEAM-A","legacyStatus":"active"}},{"rowNumber":3,"rowKey":"EXIST-1","externalClientReference":"EXIST-1","fingerprint":"cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc","payload":{"legacyClientReference":"EXIST-1","clientName":"Existing Client","contactName":"Existing Contact","mobile":"0825550101","addressLine1":"10 Shared Test Street","suburb":"Test Suburb","city":"Pretoria","latitude":-25.70,"longitude":28.27,"drumCount":1,"serviceStartDate":"2026-01-01","collectionDay":7,"team":"TEAM-A","legacyStatus":"active"}},{"rowNumber":4,"rowKey":"BAD-1","externalClientReference":"BAD-1","fingerprint":"dddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddd","payload":{"legacyClientReference":"BAD-1","clientName":"Invalid Synthetic","contactName":"Bad","mobile":"bad","email":"bad","addressLine1":"","suburb":"","city":"","drumCount":0,"collectionDay":9,"team":"UNKNOWN","legacyStatus":"mystery"}}]'),'rows imported');
select is((select count(*) from app_private.client_migration_source_rows),3::bigint,'all source rows preserved');
select is((select source_payload->>'mobile' from app_private.client_migration_source_rows where source_row_key='NEW-1'),'082 123 4567','exact source snapshot preserved');
select throws_ok(format($f$select api.client_migration_import_rows(%L,%L,2,'[]',gen_random_uuid())$f$,'76000000-0000-4000-8000-000000000001',(select batch_id from migration_ids)),'40001','stale_or_frozen_batch','approved snapshot cannot be replaced');
select lives_ok(format('select api.client_migration_process(%L,%L,2,gen_random_uuid())','76000000-0000-4000-8000-000000000001',(select batch_id from migration_ids)),'batch profiles and reconciles');
select is((select canonical_data->>'mobileE164' from app_private.client_migration_row_versions v join app_private.client_migration_source_rows s using(client_migration_row_id) where s.source_row_key='NEW-1'),'+27821234567','phone normalized consistently');
select is((select canonical_data->>'email' from app_private.client_migration_row_versions v join app_private.client_migration_source_rows s using(client_migration_row_id) where s.source_row_key='NEW-1'),'new@example.invalid','email normalized consistently');
select is((select classification from app_private.client_migration_row_versions v join app_private.client_migration_source_rows s using(client_migration_row_id) where s.source_row_key='NEW-1'),'needs_review_geography_conflict','territory ambiguity requires review');
select ok((select reconciliation->'clientCandidates' @> '[{"clientId":"57000000-0000-0000-0000-000000000001"}]' from app_private.client_migration_row_versions v join app_private.client_migration_source_rows s using(client_migration_row_id) where s.source_row_key='EXIST-1'),'existing Client matched deterministically');
select ok((select jsonb_array_length(reconciliation->'addressCandidates')=1 from app_private.client_migration_row_versions v join app_private.client_migration_source_rows s using(client_migration_row_id) where s.source_row_key='EXIST-1'),'existing Address matched independently');
select ok((select reconciliation->>'activeServiceDuplicate'='true' from app_private.client_migration_row_versions v join app_private.client_migration_source_rows s using(client_migration_row_id) where s.source_row_key='EXIST-1'),'duplicate active Service detected');
select ok((select validation_errors @> '["invalid_phone","invalid_email","invalid_drum_count","unsupported_collection_day","incomplete_address","ambiguous_legacy_status"]' from app_private.client_migration_row_versions v join app_private.client_migration_source_rows s using(client_migration_row_id) where s.source_row_key='BAD-1'),'invalid row issues retained');
select is((select reconciliation->>'teamId' from app_private.client_migration_row_versions v join app_private.client_migration_source_rows s using(client_migration_row_id) where s.source_row_key='NEW-1'),'54000000-0000-0000-0000-000000000001','explicit team mapping applied');
select is((select reconciliation->>'collectionDayComparison' from app_private.client_migration_row_versions v join app_private.client_migration_source_rows s using(client_migration_row_id) where s.source_row_key='EXIST-1'),'conflict','collection day conflict surfaced');
select throws_ok(format('select api.client_migration_bulk_review_safe(%L,%L,''approve_everything'',null,gen_random_uuid())','76000000-0000-4000-8000-000000000001',(select batch_id from migration_ids)),'22023','unsafe_bulk_mode','broad approve-everything bulk mode rejected');
select is((select count(*) from app_private.clients),2::bigint,'processing creates no authoritative Clients');
select lives_ok(format('select api.client_migration_dry_run(%L,%L,3,gen_random_uuid())','76000000-0000-4000-8000-000000000001',(select batch_id from migration_ids)),'dry run completes');
select is((select count(*) from app_private.clients),2::bigint,'dry run performs zero authoritative writes');
select is((select dry_run_summary->>'rowsRejected' from app_private.client_migration_batches),'1','dry-run summary counts invalid rows');
select throws_ok(format($f$select api.client_migration_review_row(%L,%L,0,'approved','{}',null,gen_random_uuid())$f$,'76000000-0000-4000-8000-000000000001',(select client_migration_row_id from app_private.client_migration_source_rows where source_row_key='NEW-1')),'22023','override_reason_required','material row override requires reason');
select lives_ok(format($f$select api.client_migration_review_row(%L,%L,0,'approved',%L::jsonb,'approved synthetic migration',gen_random_uuid())$f$,'76000000-0000-4000-8000-000000000001',(select s.client_migration_row_id from app_private.client_migration_source_rows s where source_row_key='NEW-1'),(select proposed_plan from app_private.client_migration_row_versions v join app_private.client_migration_source_rows s using(client_migration_row_id) where s.source_row_key='NEW-1')),'row plan approved');
select lives_ok(format($f$select api.client_migration_review_row(%L,%L,0,'no_change',%L::jsonb,null,gen_random_uuid())$f$,'76000000-0000-4000-8000-000000000001',(select s.client_migration_row_id from app_private.client_migration_source_rows s where source_row_key='EXIST-1'),(select proposed_plan from app_private.client_migration_row_versions v join app_private.client_migration_source_rows s using(client_migration_row_id) where s.source_row_key='EXIST-1')),'existing service marked no change');
select lives_ok(format($f$select api.client_migration_review_row(%L,%L,0,'rejected',%L::jsonb,'invalid synthetic row',gen_random_uuid())$f$,'76000000-0000-4000-8000-000000000001',(select s.client_migration_row_id from app_private.client_migration_source_rows s where source_row_key='BAD-1'),(select proposed_plan from app_private.client_migration_row_versions v join app_private.client_migration_source_rows s using(client_migration_row_id) where s.source_row_key='BAD-1')),'invalid row rejected durably');
select lives_ok(format('select api.client_migration_approve(%L,%L,4,gen_random_uuid())','76000000-0000-4000-8000-000000000001',(select batch_id from migration_ids)),'batch approval freezes reviewed plans');
select is((select lifecycle_status from app_private.client_migration_batches),'approved','batch is approved');
select is((select approval_snapshot->>'mappingVersion' from app_private.client_migration_batches),'canonical-v1','approval freezes mapping version');
select throws_ok(format($f$select api.client_migration_import_rows(%L,%L,5,'[]',gen_random_uuid())$f$,'76000000-0000-4000-8000-000000000001',(select batch_id from migration_ids)),'40001','stale_or_frozen_batch','approved source cannot change');
insert into app_private.client_migration_row_outcomes(client_migration_row_id,outcome,technical_failure_code) select client_migration_row_id,'failed','synthetic_failure' from app_private.client_migration_source_rows where source_row_key='NEW-1';
select lives_ok(format('select api.client_migration_retry_row(%L,%L,1,gen_random_uuid())','76000000-0000-4000-8000-000000000001',(select client_migration_row_id from app_private.client_migration_source_rows where source_row_key='NEW-1')),'technical row failure can retry');
select is((select outcome from app_private.client_migration_row_outcomes o join app_private.client_migration_source_rows s using(client_migration_row_id) where s.source_row_key='NEW-1'),'activated','retry activates through owning boundaries');
select ok((select count(*)>=4 from app_private.client_migration_entity_provenance),'migration provenance retained');
select is((api.client_migration_activate_row('76000000-0000-4000-8000-000000000001',(select client_migration_row_id from app_private.client_migration_source_rows where source_row_key='NEW-1'),gen_random_uuid())->>'duplicate')::boolean,true,'repeat row activation idempotent');
select lives_ok(format('select api.client_migration_activate_batch(%L,%L,5,gen_random_uuid())','76000000-0000-4000-8000-000000000001',(select batch_id from migration_ids)),'batch activation completes remaining rows independently');
select is((select reconciliation_report->>'activated' from app_private.client_migration_batches),'1','reconciliation report counts activated rows');
select is((select reconciliation_report->>'skipped' from app_private.client_migration_batches),'2','reconciliation report counts skipped rows');
select throws_ok(format('select api.client_migration_retry_row(%L,%L,1,gen_random_uuid())','76000000-0000-4000-8000-000000000001',(select client_migration_row_id from app_private.client_migration_source_rows where source_row_key='EXIST-1')),'55000','business_outcome_not_retryable','business outcome is not automatically retried');
select throws_ok(format('select api.client_migration_detail(%L,%L)','76000000-0000-4000-8000-000000000002',(select batch_id from migration_ids)),'42501',null,'Driver denied migration data');
select throws_ok(format('select api.client_migration_review_row(%L,%L,0,''approved'',%L::jsonb,''review'',gen_random_uuid())','76000000-0000-4000-8000-000000000003',(select s.client_migration_row_id from app_private.client_migration_source_rows s where source_row_key='NEW-1'),(select proposed_plan from app_private.client_migration_row_versions v join app_private.client_migration_source_rows s using(client_migration_row_id) where s.source_row_key='NEW-1')),'42501',null,'cross-region reviewer denied');
select throws_ok('set local role authenticated; select * from app_private.client_migration_source_rows','42501',null,'direct browser access denied');
select ok((select count(*)=1 from app_private.business_audit_facts where action_key='client_migration.batch_created'),'batch creation audited');
select ok((select count(*)=1 from app_private.outbox_events where event_name='ClientMigration.BatchCreated'),'safe batch event emitted');
select is((select count(*) from app_private.clients where display_name='Existing Client'),0::bigint,'no-change row does not overwrite or duplicate existing records');
select * from finish();rollback;
